CREATE TABLE IF NOT EXISTS sys_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(60) NOT NULL, role VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, account_type VARCHAR(20) NOT NULL DEFAULT 'ADMIN', customer_id BIGINT UNIQUE);
CREATE TABLE IF NOT EXISTS branch (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, address VARCHAR(200) NOT NULL, phone VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS pricing_rule (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, daily_rate DECIMAL(12,2) NOT NULL, monthly_rate DECIMAL(12,2) NOT NULL, base_fee DECIMAL(12,2) NOT NULL, mileage_rate DECIMAL(12,2) NOT NULL, deposit DECIMAL(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS vehicle (id BIGINT AUTO_INCREMENT PRIMARY KEY, plate VARCHAR(20) NOT NULL UNIQUE, brand VARCHAR(50) NOT NULL, model VARCHAR(80) NOT NULL, category VARCHAR(30) NOT NULL, color VARCHAR(30) NOT NULL, seats INT NOT NULL, purchase_date VARCHAR(10) NOT NULL, license_no VARCHAR(80) NOT NULL, mileage BIGINT NOT NULL, branch_id BIGINT NOT NULL, pricing_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, image VARCHAR(200), next_service_date VARCHAR(10), next_service_mileage BIGINT, FOREIGN KEY(branch_id) REFERENCES branch(id), FOREIGN KEY(pricing_id) REFERENCES pricing_rule(id));
CREATE TABLE IF NOT EXISTS customer (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL, identity_no VARCHAR(30) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL, license_no VARCHAR(80) NOT NULL, license_expiry VARCHAR(10) NOT NULL, category VARCHAR(30) NOT NULL, restricted BOOLEAN NOT NULL DEFAULT FALSE, notes VARCHAR(500));
CREATE TABLE IF NOT EXISTS rental_order (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(60) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, vehicle_id BIGINT NOT NULL, pickup_branch BIGINT NOT NULL, return_branch BIGINT NOT NULL, planned_start VARCHAR(30) NOT NULL, planned_end VARCHAR(30) NOT NULL, actual_start VARCHAR(30), actual_end VARCHAR(30), start_mileage BIGINT, end_mileage BIGINT, expected_mileage BIGINT NOT NULL, billing_mode VARCHAR(20) NOT NULL, daily_rate DECIMAL(12,2) NOT NULL, monthly_rate DECIMAL(12,2) NOT NULL, base_fee DECIMAL(12,2) NOT NULL, mileage_rate DECIMAL(12,2) NOT NULL, deposit DECIMAL(12,2) NOT NULL, estimated_rent DECIMAL(12,2) NOT NULL, actual_rent DECIMAL(12,2), extra_fee DECIMAL(12,2), discount DECIMAL(12,2), fee_notes VARCHAR(500), pickup_condition VARCHAR(500), return_condition VARCHAR(500), damage BOOLEAN DEFAULT FALSE, status VARCHAR(30) NOT NULL, created_at VARCHAR(30) NOT NULL, completed_at VARCHAR(30), cancelled_at VARCHAR(30), FOREIGN KEY(customer_id) REFERENCES customer(id), FOREIGN KEY(vehicle_id) REFERENCES vehicle(id), FOREIGN KEY(pickup_branch) REFERENCES branch(id), FOREIGN KEY(return_branch) REFERENCES branch(id));
CREATE INDEX IF NOT EXISTS idx_order_vehicle ON rental_order(vehicle_id, status, planned_start, planned_end);
CREATE TABLE IF NOT EXISTS payment_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, request_id VARCHAR(100) NOT NULL UNIQUE, kind VARCHAR(30) NOT NULL, direction VARCHAR(10) NOT NULL, amount DECIMAL(12,2) NOT NULL, method VARCHAR(30) NOT NULL, created_at VARCHAR(30) NOT NULL, operator VARCHAR(60) NOT NULL, FOREIGN KEY(order_id) REFERENCES rental_order(id));
CREATE TABLE IF NOT EXISTS dispatch_task (id BIGINT AUTO_INCREMENT PRIMARY KEY, vehicle_id BIGINT NOT NULL, from_branch BIGINT NOT NULL, to_branch BIGINT NOT NULL, assignee VARCHAR(60) NOT NULL, planned_start VARCHAR(30) NOT NULL, planned_end VARCHAR(30) NOT NULL, actual_start VARCHAR(30), actual_end VARCHAR(30), status VARCHAR(30) NOT NULL, notes VARCHAR(500), FOREIGN KEY(vehicle_id) REFERENCES vehicle(id), FOREIGN KEY(from_branch) REFERENCES branch(id), FOREIGN KEY(to_branch) REFERENCES branch(id));
CREATE TABLE IF NOT EXISTS maintenance_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, vehicle_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, project VARCHAR(200) NOT NULL, assignee VARCHAR(60) NOT NULL, cost DECIMAL(12,2) NOT NULL, status VARCHAR(30) NOT NULL, started_at VARCHAR(30), completed_at VARCHAR(30), next_date VARCHAR(10), next_mileage BIGINT, FOREIGN KEY(vehicle_id) REFERENCES vehicle(id));
CREATE TABLE IF NOT EXISTS settings (id BIGINT PRIMARY KEY, reminder_days INT NOT NULL, reminder_km INT NOT NULL, company_name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS operation_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, operator VARCHAR(60) NOT NULL, action VARCHAR(80) NOT NULL, target VARCHAR(100) NOT NULL, created_at VARCHAR(30) NOT NULL);
